public class Main {
    public static void main(String[] args) {
        int[] a = {2, -1, 3, -5, 4};
        int best = a[0];
        int cur = a[0];
        for(int i = 1; i < a.length; i++) {
            if(cur < 0) {
                cur = a[i];
            } else {
                cur = cur + a[i];
            }
            if(cur > best) {
                best = cur;
            }
        }
        System.out.println(best);
    }
}

public class Main {
    static int[] twist(int[] a) {
        int[] b = new int[a.length];
        for(int i = 0; i < a.length; i++) {
            b[i] = a[a.length - 1 - i];
        }
        return b;
    }
    public static void main(String[] args) {
        int[] src = {1, 2, 3, 4, 5};
        int[] dst = twist(src);
        dst[0] = 100;
        System.out.println(src[0] + " " + dst[0] + " " + dst[4]);
    }
}

