public class Main {
    public static void main(String[] args) {
        int[] a = {4, 5, 6, 7};
        int first = a[0];
        for(int i = 0; i < a.length - 1; i++) {
            a[i] = a[i + 1];
        }
        a[a.length - 1] = first;
        System.out.println(a[0] + " " + a[1] + " " + a[2] + " " + a[3]);
    }
}
